// Wait for DOM to load
$(document).ready(function() {
  // Select by tag
  $('h1').text('Project Dashboard');

  // Select by class
  $('.hud-panel').css('border-color', '#00ffcc');

  // Select by ID
  $('#run-btn').addClass('active');

  // Complex CSS selectors
  $('ul.project-list > li:first-child').addClass('primary');
});

// Read values
const currentStatus = $('#status-panel').text();
const inputValue = $('#user-input').val();

// Write values
$('#status-panel').text('SYSTEMS ONLINE');
$('#user-input').val('JES-01');
$('#project-card').html('<strong>New Project</strong> loaded.');

// Attribute manipulation
$('#nav-logo').attr('src', '/assets/new-logo.png');
$('#link').attr('href', 'https://developer.mozilla.org');

// Class management
$('#alert-panel').addClass('danger glow');
$('.inactive-categories').removeClass('hidden');
$('#toggle-btn').toggleClass('active');

// Check class presence
if ($('#app').hasClass('running')) {
  console.log('App is running!');
}

// CSS property batch update
$('.hud').css({
  backgroundColor: '#001122',
  borderColor: '#00ffcc',
  boxShadow: '0 0 15px cyan'
});

// Click event
$('#run-btn').on('click', function() {
  $(this).text('STARTED!').prop('disabled', true);
});

// Hover (mouseenter + mouseleave)
$('.project-card').hover(
  function() { $(this).addClass('hovered'); },
  function() { $(this).removeClass('hovered'); }
);

// Event delegation — works on dynamically added elements
$('#project-list').on('click', '.item-btn', function() {
  $(this).closest('.project-item').remove();
});

// Basic show/hide with duration
$('#warning-panel').show(300);
$('#details').hide('fast');

// Fade transitions
$('.dashboard').fadeIn(500);
$('.loading-screen').fadeOut(400, function() {
  // Runs after fadeOut completes
  $(this).remove();
});

// Toggle with slide animation
$('#settings-btn').on('click', function() {
  $('#settings-panel').slideToggle(250);
});

// Simple JSON fetch
$.getJSON('/api/projects', function(data) {
  $.each(data, function(i, project) {
    $('#list').append('<li>' + project.name + '</li>');
  });
});

// Full AJAX with error handling
$.ajax({
  url: '/api/run',
  method: 'POST',
  contentType: 'application/json',
  data: JSON.stringify({ userId: 'JES-01' }),
  success: data => console.log('Request confirmed:', data),
  error: (xhr, status) => console.error('Request failed:', status)
});

// Method chaining — one fluid expression
$('#status-panel')
  .addClass('alert-active')
  .css('border-color', '#ff0055')
  .text('CRITICAL ALERT')
  .fadeIn(300)
  .delay(3000)
  .fadeOut(500);

// Writing a simple jQuery plugin
$.fn.glow = function(color) {
  return this.css('box-shadow', '0 0 15px ' + (color || 'cyan'));
};

// Using the plugin
$('.hud-panel').glow('#00ffcc');
